import React from 'react';
import { Line } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend,
} from 'chart.js';

ChartJS.register(
    CategoryScale,
    LinearScale,
    PointElement,
    LineElement,
    Title,
    Tooltip,
    Legend
);

const StockChart = ({ chartData }) => {
    const data = {
        labels: chartData.labels,
        datasets: [
            {
                label: 'Stock Price',
                data: chartData.values,
                fill: false,
                borderColor: 'rgba(75, 192, 192, 0.2)',
                backgroundColor: 'rgb(75, 192, 192)',
            },
        ],
    };

    const options = {
        scalces: {
            y: {
                beginAtZero: false,
            },
        },
    };

    return <Line data={data} options={options} />;
};

export default StockChart;
